using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.IdentityModel.Tokens;
using TriSend.Api.Services;
namespace TriSend.Api.Controllers;
[ApiController][Route("auth")]
public sealed class AuthController(AuthService auth,EmailOtpService emailOtp,IConfiguration configuration):ControllerBase
{
 [HttpPost("email-otp/request")] public async Task<IActionResult> RequestEmailOtp([FromBody] EmailOtpRequest request,CancellationToken ct){try{await emailOtp.RequestAsync(request.Email,request.AppId,HttpContext.Connection.RemoteIpAddress?.ToString(),ct);return Accepted(new{message="If the address is eligible, a verification code has been sent."});}catch(AuthException ex){return StatusCode(ex.StatusCode,new{code=ex.Code,message=ex.Message});}catch(InvalidOperationException){return StatusCode(503,new{code="email_otp_unavailable",message="Email verification is temporarily unavailable."});}}
 [HttpPost("email-otp/verify")] public async Task<IActionResult> VerifyEmailOtp([FromBody] EmailOtpVerifyRequest request,CancellationToken ct){try{var code=await emailOtp.VerifyAsync(request.Email,request.AppId,request.Otp,ct);return Ok(new{authCode=code,expiresInSeconds=120});}catch(AuthException ex){return StatusCode(ex.StatusCode,new{code=ex.Code,message=ex.Message});}catch(InvalidOperationException){return StatusCode(503,new{code="email_otp_unavailable",message="Email verification is temporarily unavailable."});}}
 [HttpGet("{provider}/login")] public async Task<IActionResult> Login(string provider,[FromQuery]string appId,[FromQuery]string role,[FromQuery]string redirectUri,CancellationToken ct){try{return Redirect(await auth.CreateLoginUrlAsync(provider,appId,role,redirectUri,ct));}catch(AuthException ex){return StatusCode(ex.StatusCode,new{code=ex.Code,message=ex.Message});}}
 [HttpGet("{provider}/callback")] public async Task<IActionResult> Callback(string provider,[FromQuery]string code,[FromQuery]string state,CancellationToken ct){try{return Redirect(await auth.CompleteOAuthAsync(provider,code,state,ct));}catch(AuthException ex){return StatusCode(ex.StatusCode,new{code=ex.Code,message=ex.Message,maxSessions=ex.MaxSessions});}}
 [HttpPost("exchange")] public async Task<IActionResult> Exchange([FromBody]ExchangeRequest request,CancellationToken ct){try{return Ok(await auth.ExchangeCodeAsync(request.Code,request.ReplaceOldest,Request.Headers.UserAgent.ToString(),HttpContext.Connection.RemoteIpAddress?.ToString(),ct));}catch(AuthException ex){return StatusCode(ex.StatusCode,new{code=ex.Code,message=ex.Message,maxSessions=ex.MaxSessions});}}
 [HttpPost("register")] public async Task<IActionResult> Register([FromBody]PasswordRegisterRequest request,CancellationToken ct){try{return Ok(await auth.RegisterWithPasswordAsync(request.Email,request.Password,request.Name,request.AppId,request.Role,request.ReplaceOldest,Request.Headers.UserAgent.ToString(),HttpContext.Connection.RemoteIpAddress?.ToString(),ct));}catch(AuthException ex){return StatusCode(ex.StatusCode,new{code=ex.Code,message=ex.Message,maxSessions=ex.MaxSessions});}}
 [HttpPost("login")] public async Task<IActionResult> Login([FromBody]PasswordLoginRequest request,CancellationToken ct){try{return Ok(await auth.LoginWithPasswordAsync(request.Email,request.Password,request.AppId,request.ReplaceOldest,Request.Headers.UserAgent.ToString(),HttpContext.Connection.RemoteIpAddress?.ToString(),ct));}catch(AuthException ex){return StatusCode(ex.StatusCode,new{code=ex.Code,message=ex.Message,maxSessions=ex.MaxSessions});}}
 [HttpPost("refresh")] public async Task<IActionResult> Refresh([FromBody]RefreshRequest request,CancellationToken ct){try{return Ok(await auth.RefreshAsync(request.RefreshToken,ct));}catch(AuthException ex){return StatusCode(ex.StatusCode,new{code=ex.Code,message=ex.Message});}}
 [HttpPost("logout")] public async Task<IActionResult> Logout(CancellationToken ct){var p=ValidateBearerToken();if(p is null)return Unauthorized();if(!Guid.TryParse(p.FindFirstValue(JwtRegisteredClaimNames.Sub),out var u)||!Guid.TryParse(p.FindFirstValue("sid"),out var s))return Unauthorized();await auth.LogoutAsync(u,s,ct);return Ok(new{message="Logged out."});}
 [HttpPost("logout-all")] public async Task<IActionResult> LogoutAll(CancellationToken ct){var p=ValidateBearerToken();if(p is null)return Unauthorized();if(!Guid.TryParse(p.FindFirstValue(JwtRegisteredClaimNames.Sub),out var u))return Unauthorized();await auth.LogoutAllAsync(u,ct);return Ok(new{message="All sessions revoked."});}
 [HttpGet("me")] public async Task<IActionResult> Me(CancellationToken ct){var p=ValidateBearerToken();if(p is null)return Unauthorized();if(!Guid.TryParse(p.FindFirstValue(JwtRegisteredClaimNames.Sub),out var u))return Unauthorized();return Ok(new{id=u,email=p.FindFirstValue(JwtRegisteredClaimNames.Email),name=p.FindFirstValue("name"),role=p.FindFirstValue("role"),appId=p.FindFirstValue("app"),sessionId=p.FindFirstValue("sid")});}
 [HttpGet("sessions")] public async Task<IActionResult> Sessions(CancellationToken ct){var p=ValidateBearerToken();if(p is null)return Unauthorized();if(!Guid.TryParse(p.FindFirstValue(JwtRegisteredClaimNames.Sub),out var u))return Unauthorized();return Ok(await auth.SessionsAsync(u,ct));}
 [HttpDelete("sessions/{sessionId:guid}")] public async Task<IActionResult> RevokeSession(Guid sessionId,CancellationToken ct){var p=ValidateBearerToken();if(p is null)return Unauthorized();if(!Guid.TryParse(p.FindFirstValue(JwtRegisteredClaimNames.Sub),out var u))return Unauthorized();await auth.RevokeSessionAsync(u,sessionId,ct);return NoContent();}
 private ClaimsPrincipal? ValidateBearerToken(){var h=Request.Headers.Authorization.ToString();if(!h.StartsWith("Bearer ",StringComparison.OrdinalIgnoreCase))return null;var token=h["Bearer ".Length..].Trim();var key=configuration["Auth:Jwt:SigningKey"];var issuer=configuration["Auth:Jwt:Issuer"];var audience=configuration["Auth:Jwt:Audience"];if(string.IsNullOrWhiteSpace(key)||string.IsNullOrWhiteSpace(issuer)||string.IsNullOrWhiteSpace(audience))return null;try{return new JwtSecurityTokenHandler().ValidateToken(token,new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=issuer,ValidateAudience=true,ValidAudience=audience,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),ValidateLifetime=true,ClockSkew=TimeSpan.FromSeconds(30)},out _);}catch{return null;}}
 public sealed record EmailOtpRequest(string Email,string AppId);public sealed record EmailOtpVerifyRequest(string Email,string AppId,string Otp);public sealed record ExchangeRequest(string Code,bool ReplaceOldest=false);public sealed record RefreshRequest(string RefreshToken);public sealed record PasswordRegisterRequest(string Email,string Password,string? Name,string AppId,string Role,bool ReplaceOldest=false);public sealed record PasswordLoginRequest(string Email,string Password,string AppId,bool ReplaceOldest=false);
}